export type Recipient = Readonly<{
  name: string;
  postalAddress: string;
}>;

export type ProviderRequest = Readonly<{
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}>;

export type ShippingDependencies = Readonly<{
  repository: Readonly<{
    get: (shipmentId: string) => Promise<unknown>;
    save: (shipmentId: string, record: unknown) => Promise<void>;
  }>;
  atlas: Readonly<{
    book: (request: ProviderRequest) => Promise<unknown>;
  }>;
  beacon: Readonly<{
    reserve: (request: ProviderRequest) => Promise<unknown>;
  }>;
  logger: Readonly<{
    info: (event: Record<string, unknown>) => void;
  }>;
}>;

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type AbortClassification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";

type Rejection = Readonly<{
  provider: Provider;
  reason: RefusalReason;
}>;

type ShipmentFields = Readonly<{
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}>;

type QueuedShipment = ShipmentFields &
  Readonly<{
    state: "queued";
  }>;

type DispatchedShipment = ShipmentFields &
  Readonly<{
    state: "dispatched";
    provider: Provider;
    bookingId: string;
    dispatchedAtMs: number;
  }>;

type DeferredShipment = ShipmentFields &
  Readonly<{
    state: "deferred";
    nextProvider: Provider;
    retryAtMs: number;
    rejections: readonly Rejection[];
  }>;

type UnavailableShipment = ShipmentFields &
  Readonly<{
    state: "unavailable";
    rejections: readonly Rejection[];
  }>;

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type ErrorBody =
  | Readonly<{ code: "invalid_command" | "not_found" }>
  | AbortBody;

type AbortBody = Readonly<{
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: Provider | "repository";
  classification: AbortClassification;
  rejections: readonly Rejection[];
}>;

export type ServiceResponse = Readonly<{
  status: number;
  body: PublicShipment | ErrorBody;
}>;

type Command =
  | Readonly<{ op: "get"; shipmentId: string }>
  | Readonly<{
      op: "dispatch";
      shipmentId: string;
      nowMs: number;
      recipient: Recipient;
    }>;

type ProviderOutcome =
  | Readonly<{ kind: "confirmed"; bookingId: string }>
  | Readonly<{ kind: "refused"; rejection: Rejection }>
  | Readonly<{ kind: "rate_limited"; retryAtMs: number }>
  | Readonly<{ kind: "aborted"; classification: Exclude<AbortClassification, "repository_failure"> }>;

type DispatchStart = Readonly<{
  nextProvider: Provider;
  rejections: readonly Rejection[];
}>;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isAllowedReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function isNonemptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isPositiveSafeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0;
}

function isValidRetryAtMs(value: unknown, nowMs: number): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > nowMs;
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || !isNonemptyString(value.shipmentId)) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    typeof value.nowMs !== "number" ||
    !Number.isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function parseRejection(value: unknown): Rejection | undefined {
  if (!isObject(value) || !isProvider(value.provider) || !isAllowedReason(value.reason)) {
    return undefined;
  }
  return { provider: value.provider, reason: value.reason };
}

function parseRejections(value: unknown): readonly Rejection[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }
  const rejections = value.map(parseRejection);
  if (rejections.some((rejection) => rejection === undefined)) {
    return undefined;
  }
  return rejections.filter((rejection) => rejection !== undefined);
}

function parseStoredShipment(value: unknown): StoredShipment | undefined {
  if (
    !isObject(value) ||
    value.schemaVersion !== 1 ||
    !isNonemptyString(value.id) ||
    !isNonemptyString(value.routeCode) ||
    !isPositiveSafeInteger(value.parcelGrams)
  ) {
    return undefined;
  }

  const fields = {
    schemaVersion: 1,
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  } as const;

  if (value.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    isNonemptyString(value.bookingId) &&
    typeof value.dispatchedAtMs === "number" &&
    Number.isSafeInteger(value.dispatchedAtMs) &&
    value.dispatchedAtMs >= 0
  ) {
    return {
      ...fields,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }

  const rejections = parseRejections(value.rejections);
  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    typeof value.retryAtMs === "number" &&
    Number.isSafeInteger(value.retryAtMs) &&
    value.retryAtMs >= 0 &&
    rejections !== undefined
  ) {
    return {
      ...fields,
      state: "deferred",
      nextProvider: value.nextProvider,
      retryAtMs: value.retryAtMs,
      rejections,
    };
  }
  if (value.state === "unavailable" && rejections !== undefined) {
    return { ...fields, state: "unavailable", rejections };
  }

  return undefined;
}

function basePublicFields(shipment: StoredShipment) {
  return {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = basePublicFields(shipment);
  switch (shipment.state) {
    case "queued":
      return { ...fields, state: "queued" };
    case "dispatched":
      return {
        ...fields,
        state: "dispatched",
        provider: shipment.provider,
        bookingId: shipment.bookingId,
        dispatchedAtMs: shipment.dispatchedAtMs,
      };
    case "deferred":
      return {
        ...fields,
        state: "deferred",
        nextProvider: shipment.nextProvider,
        retryAtMs: shipment.retryAtMs,
        rejections: shipment.rejections.map(copyRejection),
      };
    case "unavailable":
      return {
        ...fields,
        state: "unavailable",
        rejections: shipment.rejections.map(copyRejection),
      };
  }
}

function copyRejection(rejection: Rejection): Rejection {
  return { provider: rejection.provider, reason: rejection.reason };
}

function abortBody(
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: AbortClassification,
  rejections: readonly Rejection[],
): AbortBody {
  return {
    code: "dispatch_aborted",
    shipmentId,
    failedAt,
    classification,
    rejections: rejections.map(copyRejection),
  };
}

function emitAbort(
  dependencies: ShippingDependencies,
  body: AbortBody,
): void {
  dependencies.logger.info({
    shipmentId: body.shipmentId,
    action: "aborted",
    failedAt: body.failedAt,
    classification: body.classification,
    rejections: body.rejections.map(copyRejection),
  });
}

function providerRequest(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

async function callProvider(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<ProviderOutcome> {
  try {
    const response =
      provider === "atlas"
        ? await dependencies.atlas.book(request)
        : await dependencies.beacon.reserve(request);
    return confirmProvider(provider, response);
  } catch (rejected) {
    return classifyProviderRejection(provider, rejected, nowMs);
  }
}

function confirmProvider(provider: Provider, response: unknown): ProviderOutcome {
  if (!isObject(response)) {
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (provider === "atlas" && isNonemptyString(response.bookingId)) {
    return { kind: "confirmed", bookingId: response.bookingId };
  }
  if (provider === "beacon" && isNonemptyString(response.reference)) {
    return { kind: "confirmed", bookingId: response.reference };
  }
  return { kind: "aborted", classification: "invalid_provider_response" };
}

function classifyProviderRejection(
  provider: Provider,
  rejected: unknown,
  nowMs: number,
): ProviderOutcome {
  if (!isObject(rejected)) {
    return { kind: "aborted", classification: "unknown_failure" };
  }

  if (provider === "atlas") {
    if (rejected.code === "cannot_ship") {
      if (!isAllowedReason(rejected.reason)) {
        return { kind: "aborted", classification: "invalid_provider_response" };
      }
      return {
        kind: "refused",
        rejection: { provider: "atlas", reason: rejected.reason },
      };
    }
    if (rejected.code === "rate_limited") {
      if (!isValidRetryAtMs(rejected.retryAtMs, nowMs)) {
        return { kind: "aborted", classification: "invalid_provider_response" };
      }
      return { kind: "rate_limited", retryAtMs: rejected.retryAtMs };
    }
    return { kind: "aborted", classification: "unknown_failure" };
  }

  if (rejected.type === "rejected") {
    if (!isObject(rejected.details) || !isAllowedReason(rejected.details.reason)) {
      return { kind: "aborted", classification: "invalid_provider_response" };
    }
    return {
      kind: "refused",
      rejection: { provider: "beacon", reason: rejected.details.reason },
    };
  }
  if (rejected.type === "throttled") {
    if (!isObject(rejected.details) || !isValidRetryAtMs(rejected.details.retryAtMs, nowMs)) {
      return { kind: "aborted", classification: "invalid_provider_response" };
    }
    return { kind: "rate_limited", retryAtMs: rejected.details.retryAtMs };
  }
  return { kind: "aborted", classification: "unknown_failure" };
}

function dispatchStart(shipment: StoredShipment, nowMs: number): DispatchStart | ServiceResponse {
  switch (shipment.state) {
    case "queued":
      return { nextProvider: "atlas", rejections: [] };
    case "deferred":
      if (nowMs < shipment.retryAtMs) {
        return { status: 202, body: publicShipment(shipment) };
      }
      return {
        nextProvider: shipment.nextProvider,
        rejections: shipment.rejections.map(copyRejection),
      };
    case "dispatched":
      return { status: 200, body: publicShipment(shipment) };
    case "unavailable":
      return { status: 422, body: publicShipment(shipment) };
  }
}

function nextProviderAfterRefusal(provider: Provider): Provider | undefined {
  return provider === "atlas" ? "beacon" : undefined;
}

function hasRefusal(rejections: readonly Rejection[], provider: Provider): boolean {
  return rejections.some((rejection) => rejection.provider === provider);
}

async function saveDecision(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  record: StoredShipment,
  abortRejections: readonly Rejection[],
): Promise<ServiceResponse | undefined> {
  try {
    await dependencies.repository.save(shipment.id, record);
    return undefined;
  } catch {
    const body = abortBody(
      shipment.id,
      "repository",
      "repository_failure",
      abortRejections,
    );
    emitAbort(dependencies, body);
    return { status: 500, body };
  }
}

async function dispatchShipment(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  command: Extract<Command, { op: "dispatch" }>,
): Promise<ServiceResponse> {
  const start = dispatchStart(shipment, command.nowMs);
  if ("status" in start) {
    return start;
  }

  let provider = start.nextProvider;
  let rejections = start.rejections.map(copyRejection);

  while (!hasRefusal(rejections, provider)) {
    const outcome = await callProvider(
      dependencies,
      provider,
      providerRequest(shipment, command.recipient),
      command.nowMs,
    );

    if (outcome.kind === "confirmed") {
      const dispatched: DispatchedShipment = {
        schemaVersion: 1,
        id: shipment.id,
        routeCode: shipment.routeCode,
        parcelGrams: shipment.parcelGrams,
        state: "dispatched",
        provider,
        bookingId: outcome.bookingId,
        dispatchedAtMs: command.nowMs,
      };
      const saveFailure = await saveDecision(dependencies, shipment, dispatched, rejections);
      if (saveFailure) {
        return saveFailure;
      }
      dependencies.logger.info({
        shipmentId: shipment.id,
        action: "dispatched",
        provider,
      });
      return { status: 200, body: publicShipment(dispatched) };
    }

    if (outcome.kind === "rate_limited") {
      const deferred: DeferredShipment = {
        schemaVersion: 1,
        id: shipment.id,
        routeCode: shipment.routeCode,
        parcelGrams: shipment.parcelGrams,
        state: "deferred",
        nextProvider: provider,
        retryAtMs: outcome.retryAtMs,
        rejections: rejections.map(copyRejection),
      };
      const saveFailure = await saveDecision(dependencies, shipment, deferred, rejections);
      if (saveFailure) {
        return saveFailure;
      }
      dependencies.logger.info({
        shipmentId: shipment.id,
        action: "deferred",
        provider,
        retryAtMs: outcome.retryAtMs,
        rejections: rejections.map(copyRejection),
      });
      return { status: 202, body: publicShipment(deferred) };
    }

    if (outcome.kind === "aborted") {
      const body = abortBody(shipment.id, provider, outcome.classification, rejections);
      emitAbort(dependencies, body);
      return { status: 500, body };
    }

    rejections = [...rejections, copyRejection(outcome.rejection)];
    const followingProvider = nextProviderAfterRefusal(provider);
    if (followingProvider === undefined) {
      const unavailable: UnavailableShipment = {
        schemaVersion: 1,
        id: shipment.id,
        routeCode: shipment.routeCode,
        parcelGrams: shipment.parcelGrams,
        state: "unavailable",
        rejections: rejections.map(copyRejection),
      };
      const saveFailure = await saveDecision(dependencies, shipment, unavailable, rejections);
      if (saveFailure) {
        return saveFailure;
      }
      dependencies.logger.info({
        shipmentId: shipment.id,
        action: "unavailable",
        rejections: rejections.map(copyRejection),
      });
      return { status: 422, body: publicShipment(unavailable) };
    }
    provider = followingProvider;
  }

  const body = abortBody(shipment.id, provider, "invalid_provider_response", rejections);
  emitAbort(dependencies, body);
  return { status: 500, body };
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      const body = abortBody(
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
      emitAbort(dependencies, body);
      return { status: 500, body };
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(value);
    if (shipment === undefined) {
      const body = abortBody(
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
      emitAbort(dependencies, body);
      return { status: 500, body };
    }
    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }

    return dispatchShipment(dependencies, shipment, command);
  }

  return { handle };
}
